CREATE SCHEMA coinpsi;
CREATE TABLE coinpsi.admin_users(id bigint PRIMARY KEY, username text, full_name text, email text, role text, is_active boolean);
CREATE TABLE coinpsi.knowledge_categories(id bigint PRIMARY KEY,name varchar(100),slug varchar(120),description varchar(300),is_active boolean DEFAULT true,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE TABLE coinpsi.knowledge_posts(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,title varchar(180) NOT NULL,slug varchar(200) UNIQUE NOT NULL,summary varchar(350) NOT NULL,content text NOT NULL,cover_image_url varchar(500),author_name varchar(150) NOT NULL,category_id bigint NOT NULL REFERENCES coinpsi.knowledge_categories(id),status varchar(20) NOT NULL DEFAULT 'draft',is_featured boolean NOT NULL DEFAULT false,show_on_landing boolean NOT NULL DEFAULT false,display_order smallint,created_by bigint NOT NULL REFERENCES coinpsi.admin_users(id),updated_by bigint REFERENCES coinpsi.admin_users(id),published_at timestamptz,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now(),CHECK(NOT show_on_landing OR status='published'));
